import {analyze,runCycles} from './simulation.mjs?v=20260926-1';
import {DraftHistory} from './history.mjs?v=20260926-1';
import {compile,step,encode,template,validateDraft} from './engine.mjs?v=20260926-1';
import {t,esc} from './ui.mjs?v=20260926-1';
let nodes=template(),state=[],tick=0,source=null,history=new DraftHistory();try{const saved=localStorage.getItem('cirra-draft-v1');if(saved)nodes=validateDraft(JSON.parse(saved));}catch{}
let storageError=false,trace=[];
const save=()=>{try{localStorage.setItem('cirra-draft-v1',JSON.stringify({version:1,nodes}));storageError=false;}catch{storageError=true;}};
function backup(){history.checkpoint(nodes);source=null;}
function wirePath(p,n,i){const x=p.x+128,y=p.y+53,tx=n.x,ty=n.y+50+i*24,bend=Math.max(45,Math.abs(tx-x)*0.45);return `M${x},${y} C${x+bend},${y} ${tx-bend},${ty} ${tx},${ty}`;}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function mountStudio(app,onFill){let project='';try{project=localStorage.getItem('fillout-studio-project')||'';}catch{}const $=s=>app.querySelector(s);app.innerHTML=`<section class="circuit-editor"><div class="studio-head"><div><div class="eyebrow">FILLOUT / CIRCUIT STUDIO</div><h1>${t('Circuit workspace','电路工作区')}</h1><p class="studio-subtitle">${t('Design, connect and simulate. No wallet needed.','设计、连接、模拟，无需钱包。')}</p></div><div class="actions editor-files"><button id="undo" title="Ctrl / Cmd + Z">↶ ${t('Undo','撤销')}</button><button id="redo" title="Ctrl / Cmd + Shift + Z">↷ ${t('Redo','重做')}</button><button id="import">${t('Import','导入')}</button><button id="export">${t('Export draft','导出草稿')}</button><button id="reset-workspace">${t('Reset workspace','重置工作区')}</button></div></div>
<div class="studio-grid"><aside class="toolbox"><div class="panel-heading">${t('Components','组件')}</div><p class="palette-note">${t('Click to add to canvas','点击添加到画布')}</p>${[['input','Input pin','输入端口','IN','Signal source','信号源'],['nand','Quote','Quote','⊼','NAND logic','与非逻辑'],['mem','Settle','Settle','▣','1-bit memory','一位存储'],['output','Output pin','输出端口','OUT','Read a signal','读取信号']].map(([type,en,zh,icon,desc,descZh])=>`<button data-add="${type}" class="component-button"><span class="component-symbol">${icon}</span><span class="component-copy"><strong>${t(en,zh)}</strong><small>${t(desc,descZh)}</small></span><span class="component-plus">+</span></button>`).join('')}
<div class="palette-examples"><label for="example">${t('Start from an example','从示例开始')}</label><select id="example"><option value="">${t('Choose example','选择示例')}</option><option value="nand">Quote / NAND</option><option value="not">NOT</option><option value="memory">Settle / Memory</option></select><p class="hint">${t('Examples replace your draft. Export first to keep it.','示例会替换草稿，请先导出保留。')}</p></div>
<details class="editor-help"><summary>${t('Quick guide','快速指南')}</summary><ol><li>${t('Add parts, then drag an output port to an input port.','添加组件，将输出端口拖到输入端口。')}</li><li>${t('Click an input bit to switch 0 / 1. Quote updates immediately.','点击输入切换 0 / 1，Quote 立即更新。')}</li><li>${t('Step +1 advances Settle memory.','运行一步更新 Settle 存储。')}</li></ol><p>${t('Click wires to disconnect. Drag node headers to move. Esc cancels a wire.','点击连线断开，拖动标题移动节点，Esc 取消连线。')}</p></details></aside>
<div class="editor-center"><div class="canvas-topline"><span>${t('DESIGN CANVAS','设计画布')}</span><span>${t('Draft stored locally','草稿本地保存')}</span></div><div class="canvas-wrap"><div class="canvas" id="canvas"></div></div><div class="canvas-bottomline"><span>${t('Drag ports to connect · Click bits to toggle','拖动端口连接 · 点击切换输入')}</span><span>${t('Local simulation','本地模拟')}</span></div>
<div class="outputs simulation-dock"><div class="simulation-label"><h3>${t('Simulation','模拟')}</h3><span id="tick"></span></div><div id="outputs"></div><div class="actions"><button id="reset">${t('Reset simulation','重置模拟')}</button><button id="run16">${t('Run 16','运行16步')}</button><button id="step" class="primary">${t('Step +1','运行一步')}</button></div></div></div>
<aside class="inspector"><div class="panel-heading">${t('Circuit inspector','电路检查')}</div><p id="validation" role="status"></p><div id="metrics"></div><div class="publish-section"><h2>${t('Create circuit NFT','创建电路 NFT')}</h2><label class="project-choice" for="studio-project">${t('Collection','系列')}</label><select id="studio-project"><option value="">${t('Choose collection','选择系列')}</option><option value="openbook">OpenBook</option><option value="fillout">FillOut</option></select><p id="project-summary" class="hint"></p><button id="netlist">${t('Export netlist','导出网表')}</button><p class="lock-note">${t('Creating an NFT permanently locks its Quote and Settle parts. They cannot be recovered.','创建 NFT 将永久锁定 Quote 和 Settle 组件，无法取回。')}</p><button id="create-circuit" class="primary">${t('Create circuit NFT','创建电路 NFT')}</button></div></aside></div>
<details class="simulation-trace"><summary>${t('Signal history','信号历史')}<span>${t('Last 64 steps','最近64步')}</span></summary><p class="hint">${t('Discrete steps, not physical timing. Inputs stay fixed during Run 16. Reset simulation clears inputs and memory; your design stays. Reset workspace restores the starter circuit.','离散步骤，并非物理时序。运行16步时输入固定。重置模拟清空输入及存储，保留设计。重置工作区恢复初始电路。')}</p><div id="trace"></div></details><dialog id="reset-dialog" class="reset-dialog" aria-labelledby="reset-dialog-title" aria-describedby="reset-dialog-description"><h2 id="reset-dialog-title">${t('Reset workspace?','重置工作区？')}</h2><p id="reset-dialog-description">${t('All your changes will be deleted, including added parts, wiring and undo history. The starter circuit will be restored. Export your draft first if you want to keep it.','您的所有更改将被删除，包括新增组件、连线和撤销历史，并恢复初始电路。如需保留，请先导出草稿。')}</p><div class="actions"><button id="cancel-workspace-reset" autofocus>${t('Cancel','取消')}</button><button id="confirm-workspace-reset" class="primary">${t('Reset workspace','重置工作区')}</button></div></dialog><input type="file" id="file" accept=".json,application/json" hidden><p id="studio-error" role="status"></p></section>`;
const fail=()=>{$('#studio-error').textContent=t('Unable to import this draft. Use a valid FillOut draft with up to 512 nodes.','无法导入草稿。请使用最多 512 个节点的有效 FillOut 草稿。');};
function draw(){ if(storageError)$('#studio-error').textContent=t('Browser storage is unavailable. Export your draft to keep a backup.','浏览器存储不可用。请导出草稿以备份。'); $('#undo').disabled=!history.canUndo;$('#redo').disabled=!history.canRedo; $("#project-summary").textContent=project?(project==="openbook"?"OpenBook":"FillOut")+t(" Quote / Settle will be used for this circuit."," 的 Quote / Settle 将用于此电路。"):t("Select the project whose parts you want to use.","请选择要使用哪个项目的组件。");const canvas=$('#canvas');let ir,result;try{ir=compile(nodes);result=step(ir,state.length===ir.localStateCount?state:Array(ir.localStateCount).fill(0),ir.inputs.map(n=>n.value));$('#validation').className='validation-valid';$('#validation').textContent=t('✓ Circuit valid','✓ 电路有效');$('#metrics').innerHTML=[['Input pins','输入端口',ir.nInputs],['Output pins','输出端口',ir.outputs.length],['Quote','Quote',ir.ops.length],['Settle','Settle',ir.localStateCount],['Logic depth','逻辑深度',analyze(ir).depth],['Netlist bytes','网表字节数',(encode(ir).length-2)/2]].map(([en,zh,n])=>`<p>${t(en,zh)} <strong>${n}</strong></p>`).join('');}catch{ir=null;result=null;$('#validation').className='validation-incomplete';$('#validation').textContent=t('Connect all inputs. Feedback needs Settle memory.','请连接所有输入。反馈需要 Settle 存储器。');$('#metrics').textContent='—';}$('#netlist').disabled=!ir;$('#create-circuit').disabled=!ir||!(ir.ops.length+ir.localStateCount)||!onFill||!project;$('#create-circuit').onclick=()=>{if(ir&&onFill)onFill(encode(ir),ir.ops.length,ir.localStateCount,project);};$('#step').disabled=!result;$('#run16').disabled=!result;$('#trace').innerHTML=trace.length?'<table><thead><tr>'+['t','IN','STATE','OUT','NEXT'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+trace.map(r=>'<tr>'+[r.tick,r.inputs.join(''),r.state.join(''),r.outputs.join(''),r.nextState.join('')].map(x=>'<td>'+esc(String(x===''?'—':x))+'</td>').join('')+'</tr>').join('')+'</tbody></table>':'—';$('#tick').textContent=t('Step ','步骤 ')+tick;$('#outputs').innerHTML=result?result.outputs.map((v,i)=>`<span>${t("OUT","输出")} ${i} <b class="output-bit">${v}</b></span>`).join(' '):'—';
const value=n=>result&&ir.signals.has(n.id)?result.signals[ir.signals.get(n.id)]:null;
canvas.style.width=Math.max(760,...nodes.map(n=>n.x+180))+'px';canvas.style.height=Math.max(560,...nodes.map(n=>n.y+140))+'px';canvas.innerHTML=`<svg class="wires">${nodes.flatMap(n=>n.ins.map((s,i)=>{const p=nodes.find(x=>x.id===s);if(!p)return '';return `<g class="wire-link" data-wire-target="${n.id}" data-wire-pin="${i}" role="button" tabindex="0" aria-label="${t('Disconnect wire','断开连线')} ${p.id} → ${n.id}:${i}"><title>${t('Click to disconnect · Undo restores','点击断开 · 可撤销恢复')}</title><path class="wire-hit" d="${wirePath(p,n,i)}"/><path class="wire ${value(p)===1?'high':''}" d="${wirePath(p,n,i)}"/></g>`;})).join('')}</svg>`+nodes.map(n=>`<div class="node ${n.type}" style="left:${n.x}px;top:${n.y}px"><div class="node-title" data-drag="${n.id}">${({input:t('IN','输入'),output:t('OUT','输出'),nand:'Quote',mem:'Settle'})[n.type]}<button data-delete="${n.id}" aria-label="${t('Delete node','删除节点')}">×</button></div><div class="node-body">${n.type==='input'?`<button data-bit="${n.id}">${n.value}</button>`:n.type==='output'?(result?result.outputs[ir.outputs.findIndex(x=>x.id===n.id)]:'—'):n.type==='nand'?t('NAND · 2 → 1','与非门 · 2 → 1'):t('Memory: ','存储：')+(value(n)??0)}</div>${n.ins.map((s,i)=>`<button class="port in" style="top:${50+i*24}px" data-target="${n.id}" data-pin="${i}" aria-label="${t('Input port','输入端口')} ${i}"></button>`).join('')}${n.type!=='output'?`<button class="port out ${source===n.id?'chosen':''}" data-source="${n.id}" aria-label="${t('Output port','输出端口')}"></button>`:''}</div>`).join('');
const disconnect=(id,pin)=>{const n=nodes.find(x=>x.id===id);if(!n||n.ins[pin]===null)return;backup();n.ins[pin]=null;state=[];tick=0;trace=[];save();draw();};
canvas.querySelectorAll('[data-wire-target]').forEach(w=>{w.onclick=e=>{e.stopPropagation();disconnect(w.dataset.wireTarget,Number(w.dataset.wirePin));};w.onkeydown=e=>{if(['Enter',' ','Delete','Backspace'].includes(e.key)){e.preventDefault();e.stopPropagation();disconnect(w.dataset.wireTarget,Number(w.dataset.wirePin));}};});
canvas.querySelectorAll('[data-target]').forEach(b=>{b.oncontextmenu=e=>{e.preventDefault();disconnect(b.dataset.target,Number(b.dataset.pin));};b.title=t('Input: click to connect/disconnect; right-click always disconnects','输入：点击连接/断开；右键始终断开');});
canvas.querySelectorAll('[data-source]').forEach(b=>{
 b.onclick=e=>{if(e.detail===0){source=b.dataset.source;draw();}};
 b.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();const startX=e.clientX,startY=e.clientY;let moved=false;const line=document.createElementNS('http://www.w3.org/2000/svg','path');line.setAttribute('class','wire preview');canvas.querySelector('svg').append(line);b.setPointerCapture(e.pointerId);
 const cleanup=()=>{b.onpointermove=null;b.onpointerup=null;b.onpointercancel=null;b.onlostpointercapture=null;app.removeEventListener('keydown',cancelKey,true);line.remove();canvas.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));};
 const cancel=()=>{cleanup();source=null;draw();};const cancelKey=v=>{if(v.key==='Escape'){v.stopImmediatePropagation();cancel();}};app.addEventListener('keydown',cancelKey,true);
 b.onpointermove=v=>{moved ||= Math.hypot(v.clientX-startX,v.clientY-startY)>4;const r=canvas.getBoundingClientRect(),br=b.getBoundingClientRect(),x=br.x+br.width/2-r.x,y=br.y+br.height/2-r.y,tx=v.clientX-r.x,ty=v.clientY-r.y;line.setAttribute('d','M'+x+','+y+' C'+(x+60)+','+y+' '+(tx-60)+','+ty+' '+tx+','+ty);canvas.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));document.elementFromPoint(v.clientX,v.clientY)?.closest('[data-target]')?.classList.add('drop-target');};
 b.onpointerup=v=>{const target=document.elementFromPoint(v.clientX,v.clientY)?.closest('[data-target]');cleanup();if(moved){source=b.dataset.source;if(target&&canvas.contains(target))target.click();else{source=null;draw();}}else{source=b.dataset.source;draw();}};b.onpointercancel=cancel;b.onlostpointercapture=cancel;
 };
});canvas.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const target=nodes.find(n=>n.id===b.dataset.target),pin=Number(b.dataset.pin);if(!source){if(target.ins[pin]===null)return;backup();target.ins[pin]=null;}else{const chosen=source;if(target.ins[pin]===chosen){source=null;draw();return;}backup();target.ins[pin]=chosen;}source=null;state=[];tick=0;trace=[];save();draw();});canvas.querySelectorAll('[data-bit]').forEach(b=>b.onclick=()=>{backup();nodes.find(n=>n.id===b.dataset.bit).value^=1;save();draw();});canvas.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{backup();nodes=nodes.filter(n=>n.id!==b.dataset.delete);nodes.forEach(n=>n.ins=n.ins.map(i=>i===b.dataset.delete?null:i));state=[];tick=0;trace=[];save();draw();});canvas.querySelectorAll('[data-drag]').forEach(el=>el.onpointerdown=e=>{
 if(e.button!==0||e.target.closest('button'))return;
 const n=nodes.find(n=>n.id===el.dataset.drag),x=n.x,y=n.y,cx=e.clientX,cy=e.clientY,before=JSON.parse(JSON.stringify(nodes));
 el.setPointerCapture(e.pointerId);
 el.onpointermove=v=>{n.x=Math.max(10,Math.min(1900,x+v.clientX-cx));n.y=Math.max(10,Math.min(1900,y+v.clientY-cy));el.parentElement.style.left=n.x+'px';el.parentElement.style.top=n.y+'px';canvas.querySelectorAll('[data-wire-target]').forEach(w=>{const dest=nodes.find(z=>z.id===w.dataset.wireTarget),pin=Number(w.dataset.wirePin),origin=nodes.find(z=>z.id===dest.ins[pin]);if(origin)w.querySelectorAll('path').forEach(path=>path.setAttribute('d',wirePath(origin,dest,pin)));});};
 const finish=cancel=>{el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;el.onlostpointercapture=null;if(cancel){n.x=x;n.y=y;}else if(n.x!==x||n.y!==y){history.checkpoint(before);source=null;save();}draw();};
 el.onpointerup=()=>finish(false);el.onpointercancel=()=>finish(true);el.onlostpointercapture=()=>finish(true);
});const advance=count=>{if(!result)return;const run=runCycles(ir,state.length===ir.localStateCount?state:Array(ir.localStateCount).fill(0),ir.inputs.map(n=>n.value),count,tick);trace=[...trace,...run.rows].slice(-64);state=run.state;tick+=count;draw();};$('#step').onclick=()=>advance(1);$('#run16').onclick=()=>advance(16);$('#netlist').onclick=()=>download({format:'acdv/1',binaryHex:encode(ir)},'fillout-netlist.json');}
app.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(nodes.length>=512)return;backup();const type=b.dataset.add;nodes.push({id:'n'+(Math.max(0,...nodes.map(n=>Number(n.id.slice(1))))+1),type,x:80+(nodes.length%5)*130,y:60+(nodes.length%4)*100,ins:Array(type==='nand'?2:type==='input'?0:1).fill(null),...(type==='input'?{value:0}:{})});state=[];tick=0;trace=[];save();draw();});function restore(direction){const restored=history[direction](nodes);if(!restored)return;nodes=restored;state=[];tick=0;trace=[];source=null;save();draw();}
$('#reset-workspace').onclick=()=>$('#reset-dialog').showModal();
$('#cancel-workspace-reset').onclick=()=>$('#reset-dialog').close();
$('#confirm-workspace-reset').onclick=()=>{$('#reset-dialog').close();nodes=template();state=[];tick=0;trace=[];source=null;history=new DraftHistory();$('#example').value='';$('#file').value='';const wrap=app.querySelector('.canvas-wrap');wrap.scrollTop=0;wrap.scrollLeft=0;$('#studio-error').textContent='';save();draw();if(!storageError)$('#studio-error').textContent=t('Workspace reset to the starter circuit.','工作区已恢复初始电路。');};
$('#undo').onclick=()=>restore('undo');$('#redo').onclick=()=>restore('redo');
app.onkeydown=e=>{if(!app.querySelector('#canvas')||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();restore(e.shiftKey?'redo':'undo');}else if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();restore('redo');}else if(e.key==='Escape'){source=null;draw();}};
if(!app.hasAttribute('tabindex'))app.tabIndex=-1;
$('#example').onchange=e=>{if(e.target.value){backup();nodes=template(e.target.value);state=[];tick=0;trace=[];save();draw();}};$('#export').onclick=()=>download({version:1,nodes},'fillout-draft.json');$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>500000)throw Error();const n=validateDraft(JSON.parse(await f.text()));backup();nodes=n;state=[];tick=0;trace=[];save();draw();}catch{fail();}finally{e.target.value='';}};$('#reset').onclick=()=>{backup();nodes.forEach(n=>{if(n.type==='input')n.value=0;});state=[];tick=0;trace=[];source=null;save();draw();$('#studio-error').textContent=t("Simulation reset: inputs and memory are 0.","模拟已重置：输入和存储状态均为 0。");};$('#studio-project').value=project;$('#studio-project').onchange=e=>{project=e.target.value;try{localStorage.setItem('fillout-studio-project',project);}catch{storageError=true;}draw();};draw();}
